'use strict'

const { buildPageUiModel } = require('./../build-ui-model')

module.exports = (...args) => {
  const { data, hash: params } = args.pop()
  const ref = args.length ? args[0] : data.root.page.relativeSrcPath
  if (!ref) return
  const { contentCatalog, page, site } = data.root
  let raw = false
  if ('model' in params) {
    if (!params.model) raw = true
    delete params.model
  }
  const context = page.component
    ? Object.assign({ component: page.component.name, version: page.version, module: page.module }, params)
    : params
  const file = contentCatalog.resolvePage(ref, context)
  if (file) return raw ? file : buildPageUiModel(site, file, contentCatalog)
}
